/*
ATTENTION ADMINISTRATORS:

This is the CSS for all skins. Any major changes to this page or
[[MediaWiki:Monobook.css|Monobook.css]] should be first proposed on
the [[Wikipedia:Village pump (technical)|Village pump]].  

Testing can be done on your own user Monobook.css. In [[Mozilla]] and
[[Opera (web browser)|Opera]], you can also test style changes dynamically
with the [http://www.squarefree.com/bookmarklets/webdevel.html test styles]
bookmarklet from squarefree.com. It pops up a window for adding style rules,
and updates the page as you type.

See also: [[Wikipedia:Catalogue of CSS classes|catalogue of CSS classes]].

Thank you.
*/

/* Persian Wikipedia UI fonts configurations, see also MediaWiki:Print.css
   These are writtern over the time on Monobook.css and Vector.css and shouldn't
   be changed radically without users consensus */
body {
  /* generally a sans-serif font should be here */
  font-family: Tahoma, 'Iranian Sans', 'DejaVu Sans', 'Noto Sans', 'Droid Arabic Kufi', sans-serif;
}

div#content h1, div#content h2, div#content #firstHeading,
div#content .mw-editsection,
div#content #toc h2, div#content .toc h2 {
  /* generally a serif font should be here but Arial is not acceptable for Persian */
  font-family: Tahoma, 'Iranian Serif', 'Noto Serif', 'Droid Arabic Naskh', 'Iranian Sans', 'DejaVu Sans', serif;
}

/* Main page fixes */
#interwiki-completelist {
    font-weight: bold;
} 
body.page-صفحهٔ_اصلی #mp-topbanner {
   clear: both;
}
body.page-صفحهٔ_اصلی #ca-delete,
body.page-صفحهٔ_اصلی #deleteconfirm,
body.page-صفحهٔ_اصلی #t-cite,
body.page-صفحهٔ_اصلی #lastmod,
body.page-صفحهٔ_اصلی #siteSub,
body.page-صفحهٔ_اصلی #contentSub,
body.page-صفحهٔ_اصلی #catlinks,
body.page-صفحهٔ_اصلی h1.firstHeading {
    display: none !important;
}

/* حذف سردر صفحهٔ اصلی */
.page-ویکی‌واژه_صفحهٔ_اصلی #lastmod,
.page-ویکی‌واژه_صفحهٔ_اصلی #siteSub,
.page-ویکی‌واژه_صفحهٔ_اصلی #contentSub,
/* .page-ویکی‌واژه_صفحهٔ_اصلی #siteNotice, */
.page-ویکی‌واژه_صفحهٔ_اصلی h1.firstHeading,
.page-ویکی‌واژه_صفحهٔ_اصلی #lastmod,
.page-ویکی‌واژه_صفحهٔ_اصلی #siteSub,
.page-ویکی‌واژه_صفحهٔ_اصلی #contentSub,
.page-ویکی‌واژه_صفحهٔ_اصلی #firstHeading {
display: none; /* NOT important */
}

/* Make the list of references in [[Template:Reflist]] smaller */
.references-small { 
    font-size: 90%;
}

/* Highlight clicked reference in blue to help navigation */
ol.references > li:target,
sup.reference:target,
span.citation:target, cite:target { 
    background-color: #DEF;
}

/* Ensure refs in table headers and the like aren't bold or italic */
sup.reference {
    font-weight: normal;
    font-style: normal;
}

/* Styling for citations */
span.citation, cite {
    font-style: normal;
    word-wrap: break-word;
}

/* If there is an inline link to a full citation, the full citation will turn blue when the inline link is clicked */
cite:target { 
    background-color: #DEF;
}

/* For linked citation numbers and document IDs, where the number need not be shown on a screen or a handheld, but should be included in the printed version */

@media screen, handheld, projection {
    cite *.printonly {
        display: none;
    }
}

/* wikitable/prettytable class for skinning normal tables */
table.wikitable,
table.prettytable {
    margin: 1em 1em 1em 0;
    background: #f9f9f9;
    border: 1px #aaa solid;
    border-collapse: collapse;
}

table.wikitable th, table.wikitable td,
table.prettytable th, table.prettytable td {
    border: 1px #aaa solid;
    padding: 0.2em;
}

table.wikitable th,
table.prettytable th {
    background: #f2f2f2;
    text-align: center;
}

table.wikitable caption,
table.prettytable caption {
    margin-right: inherit;
    margin-left: inherit;
    font-weight: bold;
}

table.prettytable code,
table.wikitable code {
    background-color: transparent;
}

/* Default skin for navigation boxes */
table.navbox {            /* Navbox container style */
    border: 1px solid #aaa;
    width: 100%; 
    margin: auto;
    clear: both;
    font-size: 88%;
    text-align: center;
    padding: 1px;
}
table.navbox + table.navbox {  /* Single pixel border between adjacent navboxes */
    margin-top: -1px;          /* (doesn't work for IE6, but that's okay)       */
}
.navbox-title,
.navbox-abovebelow,
table.navbox th {
    text-align: center;      /* Title and above/below styles */
    padding-left: 1em;
    padding-right: 1em;
}
.navbox-group {              /* Group style */
    white-space: nowrap;
    text-align: right;
    font-weight: bold;
    padding-left: 1em;
    padding-right: 1em;
}
.navbox, .navbox-subgroup {
    background: #fdfdfd;     /* Background color */
}
.navbox-list {
    border-color: #fdfdfd;   /* Must match background color */
}
.navbox-title,
table.navbox th {
    background: #ccccff;     /* Level 1 color */
}
.navbox-abovebelow,
.navbox-group,
.navbox-subgroup .navbox-title {
    background: #ddddff;     /* Level 2 color */
}
.navbox-subgroup .navbox-group, .navbox-subgroup .navbox-abovebelow {
    background: #e6e6ff;     /* Level 3 color */
}
.navbox-even {
    background: #f7f7f7;     /* Even row striping */
}
.navbox-odd {
    background: transparent; /* Odd row striping */
}

.collapseButton {          /* 'show'/'hide' buttons created dynamically */
    float: left;           /* by the CollapsibleTables javascript in    */
    font-weight: normal;   /* [[MediaWiki:Common.js]] are styled here   */
    text-align: left;      /* so they can be customised.                */
    width: auto;
}
.navbox .collapseButton {  /* In navboxes, the show/hide button balances */
    width: 6em;            /* the vde links from [[Template:Navbar]],    */
}                          /* so they need to be the same width.         */

.navbar {                  /* Navbox template links */
    font-size: 88%;        /* Default font-size */
    font-weight: normal;
}
.navbox .navbar {
    font-size: 100%;       /* Font-size when nested within navbox */
}

/* Infobox template style */
.infobox {
    border: 1px solid #aaa;
    background-color: #f9f9f9;
    color: black;
    margin: 0.5em 1em 0.5em 0;
    padding: 0.2em;
    float: left;
    clear: left;
}
.infobox td,
.infobox th {
    vertical-align: top;
}
.infobox caption {
    font-size: larger;
    margin-right: inherit;
}
.infobox.bordered {
    border-collapse: collapse;
}
.infobox.bordered td,
.infobox.bordered th {
    border: 1px solid #aaa;
}
.infobox.bordered .borderless td,
.infobox.bordered .borderless th {
    border: 0;
}

.infobox.sisterproject {
    width: 20em;
    font-size: 90%;
}

@media print {
    .infobox.sisterproject {
        display: none;
    }
}

.infobox.standard-talk {
    border: 1px solid #c0c090;
    background-color: #f8eaba;
}

/* styles for bordered infobox with merged rows */
.infobox.bordered .mergedtoprow td,
.infobox.bordered .mergedtoprow th {
    border: 0;
    border-top: 1px solid #aaa;
    border-left: 1px solid #aaa;
}

.infobox.bordered .mergedrow td,
.infobox.bordered .mergedrow th {
    border: 0;
    border-left: 1px solid #aaa;
